  1 | import { useCallback, useRef, useState, useEffect } from "react";
  2 | import { usePlayerWithAudio } from "./hooks/usePlayerWithAudio";
  3 | import { useMetadata } from "./hooks/useMetadata";
  4 | import { useTauri } from "./hooks/useTauri";
  5 | import { useAudioVisualizer } from "./hooks/useAudioVisualizer";
  6 | import {
  7 |   TitleBar,
  8 |   Playlist,
  9 |   PlayerControls,
 10 |   ProgressBar,
 11 |   StatusBar,
 12 |   DriveBrowser,
 13 |   AudioVisualizer,
 14 | } from "./components";
 15 | import type { Track } from "./types";
 16 | 
 17 | function App() {
 18 |   const {
 19 |     state,
 20 |     play,
 21 |     pause,
 22 |     next,
 23 |     prev,
 24 |     seek,
 25 |     setVolume,
 26 |     addTrack,
 27 |     toggleShuffle,
 28 |     reorderPlaylist,
 29 |     toggleFavorite,
 30 |     audioRef,
 31 |   } = usePlayerWithAudio([]);
 32 | 
 33 |   const { processFiles } = useMetadata();
 34 |   const {
 35 |     state: tauriState,
 36 |     openFilePicker,
 37 |     filePathToUrl,
 38 |     sendNotification,
 39 |     registerShortcuts,
 40 |   } = useTauri();
 41 | 
 42 |   const [isLoading, setIsLoading] = useState(false);
 43 |   const [showDrive, setShowDrive] = useState(false);
 44 | 
 45 |   const fileInputRef = useRef<HTMLInputElement>(null);
 46 | 
 47 |   // Registra atalhos de teclado (Media Session API + Tauri global shortcuts)
 48 |   useEffect(() => {
 49 |     const cleanup = registerShortcuts({
 50 |       MediaPlayPause: () => (state.isPlaying ? pause() : play()),
 51 |       MediaNextTrack: () => next(),
 52 |       MediaPrevTrack: () => prev(),
 53 |       MediaStop: () => pause(),
 54 |     });
 55 | 
 56 |     return () => {
 57 |       cleanup.then((fn) => fn());
 58 |     };
 59 |   }, [registerShortcuts, state.isPlaying, pause, play, next, prev]);
 60 | 
 61 |   // Media Session API (navegador)
 62 |   useEffect(() => {
 63 |     if (!("mediaSession" in navigator)) return;
 64 | 
 65 |     navigator.mediaSession.metadata = new MediaMetadata({
 66 |       title: state.currentTrack?.title ?? "Llama Player",
 67 |       artist: state.currentTrack?.artist ?? undefined,
 68 |       album: state.currentTrack?.album ?? undefined,
 69 |     });
 70 | 
 71 |     navigator.mediaSession.setActionHandler("play", () => play());
 72 |     navigator.mediaSession.setActionHandler("pause", () => pause());
 73 |     navigator.mediaSession.setActionHandler("nexttrack", () => next());
 74 |     navigator.mediaSession.setActionHandler("previoustrack", () => prev());
 75 |   }, [state.currentTrack, play, pause, next, prev]);
 76 | 
 77 |   // Notificação ao trocar de música
 78 |   useEffect(() => {
 79 |     if (state.currentTrack && state.isPlaying) {
 80 |       sendNotification(
 81 |         `▶ ${state.currentTrack.title}`,
 82 |         state.currentTrack.artist
 83 |           ? `Por ${state.currentTrack.artist}`
 84 |           : undefined
 85 |       );
 86 |     }
 87 |   }, [state.currentTrack?.id, state.isPlaying]); // eslint-disable-line react-hooks/exhaustive-deps
 88 | 
 89 |   const visualizer = useAudioVisualizer(audioRef, state.isPlaying);
 90 | 
 91 |   const handleSelectTrack = (track: Track) => {
 92 |     play(track);
 93 |   };
 94 | 
 95 |   const handleOpenFile = async () => {
 96 |     if (tauriState.isTauri) {
 97 |       // Usa file picker nativo do Tauri
 98 |       setIsLoading(true);
 99 |       try {
100 |         const paths = await openFilePicker();
101 |         if (!paths || paths.length === 0) return;
102 | 
103 |         // Converte paths para File objects (via fetch do asset protocol)
104 |         const tracks: Track[] = [];
105 |         for (const path of paths) {
106 |           const url = await filePathToUrl(path);
107 |           const name = path.split(/[/\\]/).pop() || path;
108 |           tracks.push({
109 |             id: `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
110 |             title: name.replace(/\.[^/.]+$/, ""),
111 |             duration: 0,
112 |             src: url,
113 |           });
114 |         }
115 | 
116 |         for (const track of tracks) {
117 |           addTrack(track);
118 |         }
119 | 
120 |         if (!state.currentTrack && tracks.length > 0) {
121 |           play(tracks[0]);
122 |         }
123 |       } catch (err) {
124 |         console.error("[Llama Player] Erro ao abrir arquivos:", err);
125 |       } finally {
126 |         setIsLoading(false);
127 |       }
128 |     } else {
129 |       // Fallback: input file HTML
130 |       fileInputRef.current?.click();
131 |     }
132 |   };
133 | 
134 |   const handleFileChange = useCallback(
135 |     async (e: React.ChangeEvent<HTMLInputElement>) => {
136 |       const files = e.target.files;
137 |       if (!files || files.length === 0) return;
138 | 
139 |       setIsLoading(true);
140 | 
141 |       try {
142 |         const fileArray = Array.from(files);
143 |         const tracks = await processFiles(fileArray);
144 | 
145 |         for (const track of tracks) {
146 |           addTrack(track);
147 |         }
148 | 
149 |         // If nothing is playing, start with the first track
150 |         if (!state.currentTrack && tracks.length > 0) {
151 |           play(tracks[0]);
152 |         }
153 |       } catch (err) {
154 |         console.error("[Llama Player] Erro ao processar arquivos:", err);
155 |       } finally {
156 |         setIsLoading(false);
157 |       }
158 | 
159 |       // Reset input so the same file can be selected again
160 |       e.target.value = "";
161 |     },
162 |     [processFiles, addTrack, state.currentTrack, play]
163 |   );
164 | 
165 |   const handleDropFiles = useCallback(
166 |     async (files: FileList) => {
167 |       setIsLoading(true);
168 |       try {
169 |         const fileArray = Array.from(files);
170 |         const tracks = await processFiles(fileArray);
171 |         for (const track of tracks) {
172 |           addTrack(track);
173 |         }
174 |         if (!state.currentTrack && tracks.length > 0) {
175 |           play(tracks[0]);
176 |         }
177 |       } catch (err) {
178 |         console.error("[Llama Player] Erro ao processar arquivos arrastados:", err);
179 |       } finally {
180 |         setIsLoading(false);
181 |       }
182 |     },
183 |     [processFiles, addTrack, state.currentTrack, play]
184 |   );
185 | 
186 |   const handleAddDriveTracks = useCallback(
187 |     (tracks: Track[]) => {
188 |       for (const track of tracks) {
189 |         addTrack(track);
190 |       }
191 |       if (!state.currentTrack && tracks.length > 0) {
192 |         play(tracks[0]);
193 |       }
194 |     },
195 |     [addTrack, state.currentTrack, play]
196 |   );
197 | 
198 |   return (
199 |     <div className="app">
200 |       <TitleBar />
201 | 
202 |       <main className="main-content">
203 |         <div className="toolbar">
204 |           <button
205 |             className="toolbar-btn"
206 |             onClick={handleOpenFile}
207 |             disabled={isLoading}
208 |             title="Abrir arquivo de áudio local"
209 |           >
210 |             {isLoading ? "⏳ Lendo metadados..." : "📂 Arquivo local"}
211 |           </button>
212 |           <input
213 |             ref={fileInputRef}
214 |             type="file"
215 |             accept="audio/*"
216 |             multiple
217 |             style={{ display: "none" }}
218 |             onChange={handleFileChange}
219 |           />
220 |           <button
221 |             className={`toolbar-btn ${showDrive ? "toolbar-btn-active" : ""}`}
222 |             onClick={() => setShowDrive((v) => !v)}
223 |             title="Google Drive"
224 |           >
225 |             ☁️ Drive
226 |           </button>
227 |         </div>
228 | 
229 |         {showDrive && (
230 |           <DriveBrowser onAddTracks={handleAddDriveTracks} />
231 |         )}
232 | 
233 |         <Playlist
234 |           tracks={state.playlist}
235 |           currentTrackId={state.currentTrack?.id ?? null}
236 |           isPlaying={state.isPlaying}
237 |           onSelectTrack={handleSelectTrack}
238 |           onReorderPlaylist={reorderPlaylist}
239 |           onDropFiles={handleDropFiles}
240 |           onToggleFavorite={toggleFavorite}
241 |         />
242 | 
243 |         <PlayerControls
244 |           currentTrack={state.currentTrack}
245 |           currentTrackId={state.currentTrack?.id ?? null}
246 |           isPlaying={state.isPlaying}
247 |           isShuffled={state.isShuffled}
248 |           onPlay={() => play()}
249 |           onPause={pause}
250 |           onNext={next}
251 |           onPrev={prev}
252 |           onToggleShuffle={toggleShuffle}
253 |           onToggleFavorite={toggleFavorite}
254 |         />
255 | 
256 |         <AudioVisualizer
257 |           frequencyData={visualizer.frequencyData}
258 |           waveformData={visualizer.waveformData}
259 |           isActive={visualizer.isActive}
260 |         />
261 | 
262 |         <ProgressBar
263 |           currentTime={state.currentTime}
264 |           duration={state.duration}
265 |           onSeek={seek}
266 |         />
267 |       </main>
268 | 
269 |       <StatusBar
270 |         isPlaying={state.isPlaying}
271 |         volume={state.volume}
272 |         onVolumeChange={setVolume}
273 |       />
274 |     </div>
275 |   );
276 | }
277 | 
278 | export default App;
